/* prog38_continued_fraction.c
 * Re‑implementation of the original obfuscated binary.
 *
 * Behaviour:
 *   prog38_continued_fraction NUMERATOR DENOMINATOR
 *
 *   - If fewer than two arguments are supplied: prints "NO_INPUT\n"
 *   - If either argument is not a valid decimal integer: prints "BAD_INPUT\n"
 *   - If the denominator is zero: prints "ERROR\n"
 *   - If |NUMERATOR| > 100000 or |DENOMINATOR| > 100000: prints "OUT_OF_RANGE\n"
 *   - If the continued‑fraction expansion would need more than 200 terms:
 *       prints "ERROR\n"
 *   - Otherwise prints the continued‑fraction expansion in the form
 *       [q0; q1, q2, ... , qn]
 *     followed by a newline.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_ABS_VALUE 100000
#define MAX_TERMS     200

int main(int argc, char *argv[])
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse numerator ---------- */
    char *endptr1;
    errno = 0;
    long long num = strtoll(argv[1], &endptr1, 10);
    if (errno != 0 || *endptr1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse denominator ---------- */
    char *endptr2;
    errno = 0;
    long long den = strtoll(argv[2], &endptr2, 10);
    if (errno != 0 || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- zero denominator ---------- */
    if (den == 0) {
        puts("ERROR");
        return 0;
    }

    /* ---------- range checks ---------- */
    if (llabs(num) > MAX_ABS_VALUE || llabs(den) > MAX_ABS_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- make denominator positive (move sign to numerator) ---------- */
    if (den < 0) {
        den = -den;
        num = -num;
    }

    /* ---------- compute continued‑fraction terms ---------- */
    long long terms[MAX_TERMS];
    int term_cnt = 0;

    while (den != 0) {
        if (term_cnt >= MAX_TERMS) {
            puts("ERROR");
            return 0;
        }
        long long q = num / den;          /* integer division, truncates toward zero */
        long long r = num % den;          /* remainder, may be negative */
        terms[term_cnt++] = q;
        if (r == 0)
            break;
        num = den;
        den = r;
    }

    /* ---------- output ---------- */
    putchar('[');
    if (term_cnt > 0) {
        printf("%lld", terms[0]);
        if (term_cnt > 1) {
            printf("; ");
            for (int i = 1; i < term_cnt; ++i) {
                printf("%lld", terms[i]);
                if (i + 1 < term_cnt)
                    printf(", ");
            }
        }
    }
    putchar(']');
    putchar('\n');
    return 0;
}
